<?php use App\Helpers\{View,Csrf};?><section class="hero"><div><span class="eyebrow">PASTELES HECHOS CON CARIÑO</span><h1>Momentos dulces,<br><em>recuerdos inolvidables.</em></h1><p>Explora nuestro catálogo y gana puntos en cada compra.</p><a class="primary btn" href="#catalogo">Ver pasteles</a></div><div class="hero-art">🎂<span>🍊</span></div></section><section id="catalogo"><div class="section-head"><div><span class="eyebrow">NUESTRO CATÁLOGO</span><h2>Elige tu favorito</h2></div><input id="searchProducts" placeholder="Buscar pastel..."></div><div class="chips"><button class="chip active" data-category="all">Todos</button><?php foreach($categories as $c):?><button class="chip" data-category="<?=View::e($c['id'])?>"><?=View::e($c['name'])?></button><?php endforeach;?></div><div class="cards" id="productGrid"><?php foreach($products as $p):?><article class="product-card" data-name="<?=View::e(strtolower($p['name']))?>" data-category="<?=View::e($p['category_id'])?>"><a href="/product/<?=$p['id']?>" class="product-image"><?php if($p['image']):?><img src="<?=View::e($p['image'])?>" alt="<?=View::e($p['name'])?>"><?php else:?><span>🍰</span><?php endif;?></a><div class="product-body"><small><?=View::e($p['category_name'])?></small><h3><?=View::e($p['name'])?></h3><p><?=View::e(mb_strimwidth($p['description'],0,90,'…'))?></p><div class="product-meta"><strong>$<?=number_format($p['price'],2)?></strong><span>⭐ +<?=$p['display_points']?> pts</span></div><form method="post" action="/cart/add"><?=Csrf::field()?><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="secondary wide">Agregar al carrito</button></form></div></article><?php endforeach;?></div></section>